/// Case-sensitive keysym lookup, equivalent to
/// `xkb_keysym_from_name(name, 0)`. Returns null for unknown names and for
/// `NoSymbol` (value 0), which callers treat as "no keysym".
pub fn fromName(name: []const u8) ?u32 {
    if (lookupExact(name)) |v| return nonzero(v);
    return special(name, false);
}

/// Case-insensitive lookup, equivalent to
/// `xkb_keysym_from_name(name, XKB_KEYSYM_CASE_INSENSITIVE)`.
pub fn fromNameIgnoreCase(name: []const u8) ?u32 {
    if (lookupIgnoreCase(name)) |v| return nonzero(v);
    return special(name, true);
}

/// The canonical name xkbcommon would suggest for a case-insensitive
/// match of `name` (the "best" duplicate), or null if none matches.
pub fn suggestion(name: []const u8) ?[]const u8 {
    return lookupIgnoreCaseEntry(name);
}

fn nonzero(v: u32) ?u32 {
    return if (v == 0) null else v;
}

fn lookupExact(name: []const u8) ?u32 {
    var lo: usize = 0;
    var hi: usize = entries.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        switch (std.mem.order(u8, name, entries[mid].name)) {
            .lt => hi = mid,
            .gt => lo = mid + 1,
            .eq => return entries[mid].value,
        }
    }
    return null;
}

fn lookupIgnoreCaseEntry(name: []const u8) ?[]const u8 {
    var lo: usize = 0;
    var hi: usize = icase_order.len;
    var found: ?usize = null;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        switch (orderIgnoreCase(name, entries[icase_order[mid]].name)) {
            .lt => hi = mid,
            .gt => lo = mid + 1,
            .eq => {
                found = mid;
                break;
            },
        }
    }
    const first = found orelse return null;
    // xkbcommon keeps scanning to the LAST case-insensitive duplicate:
    // the "best" (lower-case) variant sorts last.
    var best = first;
    while (best + 1 < icase_order.len and
        orderIgnoreCase(name, entries[icase_order[best + 1]].name) == .eq)
    {
        best += 1;
    }
    return entries[icase_order[best]].name;
}

fn lookupIgnoreCase(name: []const u8) ?u32 {
    const s = lookupIgnoreCaseEntry(name) orelse return null;
    return lookupExact(s);
}

fn orderIgnoreCase(a: []const u8, b: []const u8) std.math.Order {
    const n = @min(a.len, b.len);
    for (a[0..n], b[0..n]) |ca, cb| {
        const la = std.ascii.toLower(ca);
        const lb = std.ascii.toLower(cb);
        if (la != lb) return if (la < lb) .lt else .gt;
    }
    if (a.len == b.len) return .eq;
    return if (a.len < b.len) .lt else .gt;
}

/// The non-table notations accepted by xkb_keysym_from_name.
fn special(name: []const u8, icase: bool) ?u32 {
    if (name.len == 0) return null;
    if (name[0] == 'U' or (icase and name[0] == 'u')) {
        const val = parseHex(name[1..]) orelse return null;
        if (val > 0xff and val <= 0x10ffff) return nonzero(0x01000000 + val);
        return nonzero(latin1(val));
    }
    if (name.len >= 2 and name[0] == '0' and
        (name[1] == 'x' or (icase and name[1] == 'X')))
    {
        const val = parseHex(name[2..]) orelse return null;
        if (val > 0x1fffffff) return null; // XKB_KEYSYM_MAX
        return nonzero(val);
    }
    // XKeysymDB inconsistency: "XF86_Foo" is retried as "XF86Foo".
    const prefix = "XF86_";
    if (name.len > prefix.len and
        (std.mem.startsWith(u8, name, prefix) or
            (icase and std.ascii.eqlIgnoreCase(name[0..prefix.len], prefix))))
    {
        var buf: [256]u8 = undefined;
        if (name.len - 1 > buf.len) return null;
        @memcpy(buf[0..4], name[0..4]);
        @memcpy(buf[4 .. name.len - 1], name[5..]);
        return fromNameInner(buf[0 .. name.len - 1], icase);
    }
    return null;
}

fn fromNameInner(name: []const u8, icase: bool) ?u32 {
    if (icase) {
        if (lookupIgnoreCase(name)) |v| return nonzero(v);
    } else {
        if (lookupExact(name)) |v| return nonzero(v);
    }
    return special(name, icase);
}

/// Up to 8 hex digits, whole string consumed (xkbcommon parse_keysym_hex).
fn parseHex(s: []const u8) ?u32 {
    if (s.len == 0 or s.len > 8) return null;
    var v: u32 = 0;
    for (s) |c| {
        const d = std.fmt.charToDigit(c, 16) catch return null;
        v = (v << 4) | @as(u32, d);
    }
    return v;
}

/// xkb_utf32_to_keysym restricted to code points <= 0xff (the only range
/// the U+ notation routes through it; keysymtab has no entries < 0x100).
fn latin1(v: u32) u32 {
    if ((v >= 0x20 and v <= 0x7e) or (v >= 0xa0 and v <= 0xff)) return v;
    if ((v >= 0x08 and v <= 0x0b) or v == 0x0d or v == 0x1b) return v | 0xff00;
    if (v == 0x7f) return 0xffff; // Delete
    if (v == 0) return 0; // NoSymbol
    return v | 0x01000000;
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

test "keysym table is sorted and complete" {
    try std.testing.expectEqual(@as(usize, 2638), entries.len);
    for (entries[1..], entries[0 .. entries.len - 1]) |next, prev| {
        try std.testing.expect(std.mem.order(u8, prev.name, next.name) == .lt);
    }
}

test "named keysyms used by the grab defaults" {
    try std.testing.expectEqual(@as(?u32, 0xff52), fromName("Up"));
    try std.testing.expectEqual(@as(?u32, 0xff54), fromName("Down"));
    try std.testing.expectEqual(@as(?u32, 0xff55), fromName("Prior"));
    try std.testing.expectEqual(@as(?u32, 0xff56), fromName("Next"));
    try std.testing.expectEqual(@as(?u32, 0xff53), fromName("Right"));
    try std.testing.expectEqual(@as(?u32, 0xff51), fromName("Left"));
    try std.testing.expectEqual(@as(?u32, 0x2b), fromName("plus"));
    try std.testing.expectEqual(@as(?u32, 0x3d), fromName("equal"));
    try std.testing.expectEqual(@as(?u32, 0x2d), fromName("minus"));
    try std.testing.expectEqual(@as(?u32, 0xff08), fromName("BackSpace"));
    try std.testing.expectEqual(@as(?u32, 0xff0d), fromName("Return"));
    try std.testing.expectEqual(@as(?u32, 0xffff), fromName("Delete"));
    try std.testing.expectEqual(@as(?u32, 0xffbe), fromName("F1"));
    try std.testing.expectEqual(@as(?u32, 0x61), fromName("a"));
    try std.testing.expectEqual(@as(?u32, 0x41), fromName("A"));
    try std.testing.expectEqual(@as(?u32, 0x20), fromName("space"));
}

test "keysym names are case-sensitive" {
    try std.testing.expectEqual(@as(?u32, null), fromName("up"));
    try std.testing.expectEqual(@as(?u32, null), fromName("UP"));
    try std.testing.expectEqual(@as(?u32, null), fromName("backspace"));
    try std.testing.expectEqual(@as(?u32, null), fromName("NoSymbol"));
    try std.testing.expectEqual(@as(?u32, null), fromName(""));
    try std.testing.expectEqual(@as(?u32, null), fromName("NotAKeysym"));
    // Case-insensitive lookup finds them and suggests the canonical name.
    try std.testing.expectEqual(@as(?u32, 0xff52), fromNameIgnoreCase("up"));
    try std.testing.expectEqualStrings("Up", suggestion("up").?);
    try std.testing.expectEqualStrings("BackSpace", suggestion("backspace").?);
    try std.testing.expectEqual(@as(?[]const u8, null), suggestion("NotAKeysym"));
}

test "unicode and hex notations match xkbcommon" {
    // U+ notation: direct encoding above 0xff, Latin-1 below.
    try std.testing.expectEqual(@as(?u32, 0x41), fromName("U+0041"));
    try std.testing.expectEqual(@as(?u32, 0xe9), fromName("U+00E9"));
    try std.testing.expectEqual(@as(?u32, 0x010020ac), fromName("U+20AC"));
    try std.testing.expectEqual(@as(?u32, 0x0101f600), fromName("U+1F600"));
    try std.testing.expectEqual(@as(?u32, 0xff08), fromName("U+0008"));
    try std.testing.expectEqual(@as(?u32, 0xff0d), fromName("U+000D"));
    try std.testing.expectEqual(@as(?u32, 0xffff), fromName("U+007F"));
    try std.testing.expectEqual(@as(?u32, null), fromName("U+0000"));
    try std.testing.expectEqual(@as(?u32, null), fromName("U+110000"));
    try std.testing.expectEqual(@as(?u32, null), fromName("U+"));
    try std.testing.expectEqual(@as(?u32, null), fromName("U+123456789"));
    // Raw hex notation, capped at XKB_KEYSYM_MAX.
    try std.testing.expectEqual(@as(?u32, 0xff52), fromName("0xff52"));
    try std.testing.expectEqual(@as(?u32, 0x1fffffff), fromName("0x1fffffff"));
    try std.testing.expectEqual(@as(?u32, null), fromName("0x20000000"));
    try std.testing.expectEqual(@as(?u32, null), fromName("0x"));
    // XF86_ underscore-strip fallback.
    try std.testing.expectEqual(fromName("XF86AudioLowerVolume"), fromName("XF86_AudioLowerVolume"));
}
